import { computed, defineComponent, h, inject, provide, ref, type ComputedRef, type InjectionKey, type PropType } from 'vue';
import { getToggleGroupItemState, getToggleStyleKeys, toggleGroupStyleKeys, toggleValueInList } from '../lib/core';
import type { ToggleGroupType, ToggleVariant, ToggleSize } from '../lib/core';
import styles from './toggle-group.module.scss';

type ToggleGroupValue = string | string[];

interface ToggleGroupContextValue {
	type: 'single' | 'multiple';
	value: ToggleGroupValue;
	onItemClick: (itemValue: string) => void;
}

type ToggleGroupContext = ComputedRef<ToggleGroupContextValue>;

const ToggleGroupContextKey: InjectionKey<ToggleGroupContext> = Symbol('tile-toggle-group');

export const ToggleGroup = defineComponent({
	name: 'ToggleGroup',
	props: {
		modelValue: {
			type: [String, Array] as PropType<string | string[]>,
			default: undefined,
		},
		defaultValue: {
			type: [String, Array] as PropType<string | string[]>,
			default: undefined,
		},
		type: {
			type: String as PropType<ToggleGroupType>,
			default: 'single',
		},
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit, slots, attrs }) {
		const internalValue = ref<string | string[]>(props.defaultValue ?? (props.type === 'single' ? '' : []));
		const currentValue = computed(() => (props.modelValue !== undefined ? props.modelValue : internalValue.value));

		function handleItemClick(itemValue: string) {
			let next: string | string[];

			if (props.type === 'single') {
				next = currentValue.value === itemValue ? '' : itemValue;
			} else {
				const list = Array.isArray(currentValue.value) ? currentValue.value : [];
				next = toggleValueInList(itemValue, list);
			}

			if (props.modelValue === undefined) {
				internalValue.value = next;
			}

			emit('update:modelValue', next);
			emit('change', next);
		}

		const context = computed<ToggleGroupContextValue>(() => ({
			type: props.type,
			value: currentValue.value,
			onItemClick: handleItemClick,
		}));

		provide(ToggleGroupContextKey, context);

		return () =>
			h('div', { ...attrs, role: 'group', 'data-slot': 'toggle-group', 'data-type': props.type, class: [styles[toggleGroupStyleKeys.root], attrs.class] }, slots.default?.());
	},
});

export const ToggleGroupItem = defineComponent({
	name: 'ToggleGroupItem',
	props: {
		value: { type: String, required: true },
		variant: {
			type: String as PropType<ToggleVariant>,
			default: 'default',
		},
		size: {
			type: String as PropType<ToggleSize>,
			default: 'default',
		},
		disabled: { type: Boolean, default: false },
	},
	setup(props, { slots, attrs }) {
		const context = inject(ToggleGroupContextKey);
		if (!context) {
			throw new Error('ToggleGroupItem must be used within <ToggleGroup>.');
		}
		const contextRef = context;

		const selected = computed(() =>
			contextRef.value.type === 'single'
				? contextRef.value.value === props.value
				: Array.isArray(contextRef.value.value)
					? contextRef.value.value.includes(props.value)
					: false,
		);
		const state = computed(() => getToggleGroupItemState(selected.value));
		const styleKeys = computed(() => getToggleStyleKeys(props.variant, props.size));
		const classes = computed(() => [styles[toggleGroupStyleKeys.item], styles[styleKeys.value.variant], styles[styleKeys.value.size]]);

		function handleClick() {
			contextRef.value.onItemClick(props.value);
		}

		return () =>
			h(
				'button',
				{
					...attrs,
					type: 'button',
					value: props.value,
					'aria-pressed': selected.value ? 'true' : 'false',
					'data-state': state.value,
					'data-active': selected.value,
					disabled: props.disabled,
					class: [...classes.value, attrs.class],
					onClick: handleClick,
				},
				slots.default?.(),
			);
	},
});

export default ToggleGroup;

@use '../../../styles/variables/colors' as *;

.root {
	display: inline-flex;
	width: fit-content;
	align-items: center;
	border-radius: var(--tile-toggle-group-radius, #{$radius});

	&[data-orientation='horizontal'] {
		> *:not(:first-child) {
			border-left: none;
			border-top-left-radius: 0;
			border-bottom-left-radius: 0;
		}

		> *:not(:last-child) {
			border-top-right-radius: 0;
			border-bottom-right-radius: 0;
		}
	}

	&[data-orientation='vertical'] {
		flex-direction: column;
		align-items: stretch;

		> *:not(:first-child) {
			border-top: none;
			border-top-left-radius: 0;
			border-top-right-radius: 0;
		}

		> *:not(:last-child) {
			border-bottom-right-radius: 0;
			border-bottom-left-radius: 0;
		}
	}
}

.item {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: var(--tile-toggle-group-gap, #{$spacing-2});
	white-space: nowrap;
	border-radius: var(--tile-toggle-group-radius, #{$radius});
	border: 1px solid transparent;
	font-size: var(--tile-toggle-group-font-size, #{$text-sm});
	line-height: var(--tile-toggle-group-line-height, inherit);
	font-weight: $font-medium;
	transition:
		color $transition-fast,
		background-color $transition-fast,
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	cursor: pointer;

	&:focus-visible {
		border-color: var(--tile-toggle-group-focus-border, #{$ring});
		box-shadow: var(--tile-toggle-group-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
		z-index: 1;
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
		cursor: not-allowed;
	}

	svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
	}

	// 状态
	&[data-state='on'] {
		background-color: var(--tile-toggle-group-selected-background, #{$accent});
		color: var(--tile-toggle-group-selected-color, #{$accent-foreground});
	}

	&[data-state='off'] {
		background-color: transparent;
		color: $foreground;

		&:hover:not(:disabled) {
			background-color: var(--tile-toggle-group-hover-background, #{$muted});
			color: var(--tile-toggle-group-hover-color, #{$muted-foreground});
		}
	}

	// 样式变体
	&.variantOutline {
		border-color: var(--tile-toggle-group-border, #{$border});
		box-shadow: var(--tile-toggle-group-shadow, #{$shadow-sm});
	}

	&.variantGhost {
		background-color: transparent;

		&[data-state='on'] {
			background-color: var(--tile-toggle-group-ghost-selected-background, #{$muted});
			color: var(--tile-toggle-group-ghost-selected-color, #{$muted-foreground});
		}
	}

	// 尺寸变体
	&.sizeDefault {
		height: var(--tile-toggle-group-height, 2.25rem);
		min-width: var(--tile-toggle-group-height, 2.25rem);
		padding: 0 var(--tile-toggle-group-padding-inline, #{$spacing-2});
	}

	&.sizeSm {
		height: var(--tile-toggle-group-sm-height, 2rem);
		min-width: var(--tile-toggle-group-sm-height, 2rem);
		padding: 0 var(--tile-toggle-group-sm-padding-inline, #{$spacing-1_5});
		font-size: var(--tile-toggle-group-sm-font-size, #{$text-sm});
		border-radius: var(--tile-toggle-group-sm-radius, #{$radius});
	}

	&.sizeLg {
		height: var(--tile-toggle-group-lg-height, 2.5rem);
		min-width: var(--tile-toggle-group-lg-height, 2.5rem);
		padding: 0 var(--tile-toggle-group-lg-padding-inline, #{$spacing-2_5});
	}
}
